insert into public.catalogue_master_product_identifiers(product_id,identifier_type,identifier_value,normalized_value,source_name,source_url,verification_status,notes)
select p.id,d.identifier_type,d.identifier_value,d.normalized_value,d.source_name,d.source_url,d.verification_status,d.notes from data d join public.catalogue_master_categories c on c.slug=d.category_slug left join public.catalogue_master_branches b on b.category_id=c.id and b.slug=d.branch_slug join public.catalogue_master_manufacturers m on m.name=d.manufacturer_name join public.catalogue_master_products p on p.category_id=c.id and p.branch_id is not distinct from b.id and p.manufacturer_id=m.id and p.model=d.model and p.package_key=d.package_key
on conflict (product_id,identifier_type,normalized_value) do update set identifier_value=excluded.identifier_value,source_name=excluded.source_name,source_url=excluded.source_url,verification_status=excluded.verification_status,notes=excluded.notes;
